1	//! Bench registry. Each bench module exposes `NAME` (CLI id) and
2	//! `run` (entry point). Add a bench by creating a module and
3	//! appending it to [`REGISTRY`].
4	
5	pub mod cb_chan_1t;
6	pub mod cb_chan_2t;
7	pub mod cb_seg_1t;
8	pub mod cb_seg_2t;
9	pub mod ice_ps_1t;
10	pub mod ice_ps_2t;
11	pub mod ice_rr_1t;
12	pub mod ice_rr_2t;
13	pub mod min_now;
14	pub mod mpsc_1t;
15	pub mod mpsc_2t;
16	pub mod mpsc_2t_spin;
17	pub mod probe_mpsc_2t;
18	pub mod producer_consumer;
19	pub mod std_now;
20	pub mod tp2_pc;
21	pub mod tp_pc;
22	pub mod zcr_common;
23	pub mod zcr_mpsc_v0_1t;
24	pub mod zcr_mpsc_v0_2t;
25	pub mod zcr_mpsc_v1_1t;
26	pub mod zcr_mpsc_v1_2t;
27	pub mod zcr_spsc_v0_1t;
28	pub mod zcr_spsc_v0_2t;
29	pub mod zcr_spsc_v1_1t;
30	pub mod zcr_spsc_v1_2t;
31	pub mod zcr_spsc_v2_1t;
32	pub mod zcr_spsc_v2_2t;
33	
34	use crate::harness::RunCfg;
35	
36	/// Bench entry-point signature.
37	pub type RunFn = fn(&RunCfg);
38	
39	/// Static list of every registered bench, in display order.
40	pub const REGISTRY: &[(&str, RunFn)] = &[
41	    (min_now::NAME, min_now::run),
42	    (std_now::NAME, std_now::run),
43	    (mpsc_1t::NAME, mpsc_1t::run),
44	    (mpsc_2t::NAME, mpsc_2t::run),
45	    (mpsc_2t_spin::NAME, mpsc_2t_spin::run),
46	    (probe_mpsc_2t::NAME, probe_mpsc_2t::run),
47	    (producer_consumer::NAME, producer_consumer::run),
48	    (tp_pc::NAME, tp_pc::run),
