1	//! The `qualify-environment` selftest: is this machine fit to
2	//! measure on?
3	//!
4	//! Respawns our own binary `--runs` times at `--gap`, collects
5	//! each run's environment grade, prints the table, and returns a
6	//! verdict. It tests the *machine*, not a workload, so it reads
7	//! the environment stretches rather than the run grade — see
8	//! [`crate::gauge::EnvGrade`].
9	//!
10	//! - **Why respawn** rather than loop in-process: a fresh process
11	//!   per run is what terminal use looks like, and in-process
12	//!   repeats would share warmed state — the very thing under
13	//!   test.
14	//! - **Why `min-now`** as the child workload: the box is the
15	//!   subject, so the leanest available bench is right. It also
16	//!   measures nearly what the probe measures, which keeps the run
17	//!   grade and the environment grade commensurable.
18	//! - **The verdict** is grades, not values: median environment
19	//!   grade at B or better, and no run whose `drift` or `step`
20	//!   reached D/F in either stretch. Those two are the transition
21	//!   detectors, so a D/F there is a state change landing inside a
22	//!   measurement window — the anomaly this test exists to catch.
23	//!   Wobble on `spread` or `interference` is ambient
24	//!   contamination and does not fail the run.
25	
26	use std::process::Command;
27	use std::time::Duration;
28	
29	use crate::gauge::Settle;
30	
31	/// Child bench: the leanest registered workload, so the table
32	/// reflects the box rather than a workload's character.
33	const CHILD_BENCH: &str = "min-now";
34	
35	/// Knobs for one selftest, from the CLI.
36	pub struct QualifyCfg {
37	    /// Child runs to spawn.
38	    pub runs: u64,
39	    /// Sleep before each child. Zero sustains the duty cycle that
40	    /// provokes a transition; a nonzero gap probes a quieter one.
41	    pub gap_s: f64,
42	    /// Wall-clock seconds per child run.
43	    pub duration_s: f64,
44	    /// `--pin-cpus` spec to pass through, if any.
45	    pub pin_cpus: Option<String>,
46	    /// Print the table and skip the verdict.
47	    pub print_only: bool,
48	    /// `--settle-time` to pass each child, when the parent was
49	    /// given one. Absent leaves each child on its own default, so
50	    /// the table reflects what a plain run of this binary does.
51	    pub settle_time: Option<f64>,
52	}
53	
54	/// One environment stretch parsed from a child's grade-block
55	/// row: its composite (`worst` column) and the two transition
56	/// detectors' letters.
57	struct Stretch {
58	    letter: char,
59	    drift: Option<char>,
60	    step: Option<char>,
61	}
62	
63	/// Split one report line into grade-block cells: columns are
64	/// right-aligned with a two-space minimum gap, so two-or-more
65	/// spaces is the cell separator and single spaces stay inside a
66	/// cell (`0.30% A`, `4.84->5.24GHz 49% +-0.1%`, `9.37% @1.90s D`).
67	fn row_cells(line: &str) -> Vec<&str> {
68	    line.split("  ")
69	        .map(str::trim)
70	        .filter(|s| !s.is_empty())
71	        .collect()
72	}
73	
74	/// A cell's trailing grade letter, `None` for a blank cell or
75	/// anything else that does not end in A-F.
76	fn cell_letter(cell: &str) -> Option<char> {
77	    cell.chars().last().filter(|c| ('A'..='F').contains(c))
78	}
79	
80	/// A warmup row's `settle` cell: the journey forms the harness
81	/// prints (`4.84->5.24GHz 49% +-0.0%`, `3.60->4.20GHz 0%`, and
82	/// the timing-only `49%` / `0%`), or `None` for a blank or an
83	/// `uncertified`. Format and parser move together: the child
84	/// is this same binary. `0%` is reserved for never-settled,
85	/// and the ramp-end `t_s` never reaches the cell, so a parsed
86	/// `At` carries `t_s` as zero.
87	fn parse_settle(cell: &str) -> Option<Settle> {
88	    // The report appends the settle signal's letter after the cell. The values are what
89	    // qualify reads (the letter already folded into the row's worst), so strip it.
90	    let cell = match cell.rsplit_once(' ') {
91	        Some((head, l)) if l.len() == 1 && l.chars().all(|c| c.is_ascii_uppercase()) => head,
92	        _ => cell,
93	    };
94	    let (cell, rating) = match cell.rsplit_once(" +-") {
95	        Some((head, r)) => (
96	            head,
97	            Some(r.strip_suffix('%')?.parse::<f64>().ok()? / 100.0),
98	        ),
99	        None => (cell, None),
100	    };
101	    let (head, pct) = match cell.rsplit_once(' ') {
102	        Some((h, t)) => (h, t),
103	        None => ("", cell),
104	    };
105	    let pct: f64 = pct.strip_suffix('%')?.parse().ok()?;
106	    let (start_ghz, ghz) = parse_journey(head)?;
107	    if pct == 0.0 {
108	        return Some(Settle::Never {
109	            start_ghz,
110	            end_ghz: ghz,
111	        });
112	    }
113	    Some(Settle::At {
114	        t_s: 0.0,
115	        settled_frac: pct / 100.0,
116	        start_ghz,
117	        ghz,
118	        rating,
119	    })
120	}
121	
122	/// A cell's journey prefix: `3.60->4.09GHz` -> both ends,
123	/// `4.09GHz` -> one clock at both ends, empty -> no clock.
124	/// `None` for anything else.
125	fn parse_journey(s: &str) -> Option<(Option<f64>, Option<f64>)> {
126	    if s.is_empty() {
127	        return Some((None, None));
128	    }
129	    let s = s.strip_suffix("GHz")?;
130	    match s.split_once("->") {
131	        Some((a, b)) => Some((Some(a.parse().ok()?), Some(b.parse().ok()?))),
132	        None => {
133	            let g: f64 = s.parse().ok()?;
134	            Some((Some(g), Some(g)))
135	        }
136	    }
137	}
138	
139	/// Parse one grade-block row's cells into a [`Stretch`]. Cell
140	/// order is the block's column order: grade, phase, settle,
141	/// worst, spread, bursts, interference, drift, step.
142	fn parse_stretch(cells: &[&str]) -> Stretch {
143	    Stretch {
144	        letter: cells.get(3).and_then(|c| c.chars().next()).unwrap_or('?'), // OK: short row can't happen, '?' scores worst if it does
145	        drift: cells.get(7).copied().and_then(cell_letter),
146	        step: cells.get(8).copied().and_then(cell_letter),
147	    }
148	}
149	
150	impl Stretch {
151	    /// True when a transition detector reached D/F here.
152	    fn transition_degraded(&self) -> bool {
153	        [self.drift, self.step]
154	            .into_iter()
155	            .flatten()
156	            .any(|l| l == 'D' || l == 'F')
157	    }
158	}
159	
160	/// One child run's parsed result.
161	struct QualifyRun {
162	    warmup: Option<Stretch>,
163	    during: Option<Stretch>,
164	    /// Environment composite — the worse of the two stretches,
165	    /// computed here from their `worst` columns.
166	    worst: char,
167	    /// The run's mean, for the value column: the number that makes
168	    /// a two-state box visible at a glance.
169	    mean: String,
170	    /// The child warmup's settle cell: the clock's journey and
171	    /// how long the settled state held, read across respawns.
172	    /// Reported, not judged: the verdict stays grades, because a
173	    /// box still moving at the end of warmup already shows up as
174	    /// a drift/step D/F on the warmup stretch.
175	    settle: Option<Settle>,
176	}
177	
178	impl QualifyRun {
179	    /// True when either stretch shows a transition at D/F.
180	    fn transition_degraded(&self) -> bool {
181	        [self.warmup.as_ref(), self.during.as_ref()]
182	            .into_iter()
183	            .flatten()
184	            .any(Stretch::transition_degraded)
185	    }
186	
187	    /// Per-stretch letters for the table, `-` where a stretch is
188	    /// absent (`--no-env-probe` leaves no run stretch).
189	    fn letters(&self) -> (char, char) {
190	        (
191	            self.warmup.as_ref().map_or('-', |s| s.letter),
192	            self.during.as_ref().map_or('-', |s| s.letter),
193	        )
194	    }
195	}
196	
197	/// One-line tally of the runs' composite grades, best first:
198	/// `7A 1B 1D 1F`, absent letters omitted.
199	///
200	/// - Printed beside the median because a median is a statement
201	///   about the typical run, and qualification is a question about
202	///   the bad one: a box clean on seven runs of ten reports a
203	///   median of A while three runs saw the machine move. The tally
204	///   cannot hide a tail.
205	fn grade_tally(runs: &[QualifyRun]) -> String {
206	    ['A', 'B', 'C', 'D', 'F']
207	        .into_iter()
208	        .filter_map(|l| match runs.iter().filter(|r| r.worst == l).count() {
209	            0 => None,
210	            n => Some(format!("{n}{l}")),
211	        })
212	        .collect::<Vec<_>>()
213	        .join(" ")
214	}
215	
216	/// Letter -> ordinal score, A best. Unknown letters score worst,
217	/// so a parse miss can never flatter a run.
218	fn score(letter: char) -> i64 {
219	    match letter {
220	        'A' => 5,
221	        'B' => 4,
222	        'C' => 3,
223	        'D' => 2,
224	        _ => 1,
225	    }
226	}
227	
228	/// Inverse of [`score`], for reporting a median back as a letter.
229	fn letter_for(score: i64) -> char {
230	    match score {
231	        5 => 'A',
232	        4 => 'B',
233	        3 => 'C',
234	        2 => 'D',
235	        _ => 'F',
236	    }
237	}
238	
239	/// Spawn one child and parse its report.
240	fn run_once(cfg: &QualifyCfg) -> Result<QualifyRun, String> {
241	    let exe = std::env::current_exe().map_err(|e| format!("current_exe: {e}"))?;
242	    let mut cmd = Command::new(exe);
243	    cmd.arg(CHILD_BENCH)
244	        .arg("-d")
245	        .arg(cfg.duration_s.to_string())
246	        // The parent already holds the sleep lock; a child
247	        // re-exec per run would cost more than the run.
248	        .arg("--no-inhibit");
249	    if let Some(pin) = &cfg.pin_cpus {
250	        cmd.arg("--pin-cpus").arg(pin);
251	    }
252	    if let Some(t) = cfg.settle_time {
253	        cmd.arg("--settle-time").arg(t.to_string());
254	    }
255	    let out = cmd.output().map_err(|e| format!("spawn child: {e}"))?;
256	    let text =
257	        String::from_utf8_lossy(&out.stdout).into_owned() + &String::from_utf8_lossy(&out.stderr);
258	
259	    let mut warmup = None;
260	    let mut during = None;
261	    let mut mean = String::new();
262	    let mut settle = None;
263	    for line in text.lines() {
264	        let cells = row_cells(line);
265	        if cells.first() == Some(&"env") {
266	            match cells.get(1) {
267	                Some(&"warmup") => {
268	                    settle = cells.get(2).and_then(|c| parse_settle(c));
269	                    warmup = Some(parse_stretch(&cells));
270	                }
271	                Some(&"bench") => during = Some(parse_stretch(&cells)),
272	                _ => {}
273	            }
274	        } else {
275	            // The plain `mean` row — not `mean z3..n2` (trimmed),
276	            // whose second token isn't a number.
277	            let mut tok = line.split_whitespace();
278	            if tok.next() == Some("mean")
279	                && let Some(v) = tok.next()
280	                && v.parse::<f64>().is_ok()
281	                && mean.is_empty()
282	            {
283	                mean = format!("{v} ns");
284	            }
285	        }
286	    }
287	    if warmup.is_none() && during.is_none() {
288	        return Err(format!(
289	            "no environment grade in child output ({} bytes); \
290	             child exited {}",
291	            text.len(),
292	            out.status
293	        ));
294	    }
295	    // The environment composite: the worse of the two stretch
296	    // letters, computed here now that the block prints no
297	    // composite line of its own (each row's `worst` is visible
298	    // beside its causes instead).
299	    let worst = [warmup.as_ref(), during.as_ref()]
300	        .into_iter()
301	        .flatten()
302	        .map(|s| s.letter)
303	        .min_by_key(|&c| score(c))
304	        .unwrap_or('?'); // OK: unreachable, the is_none guard above returned already
305	    Ok(QualifyRun {
306	        warmup,
307	        during,
308	        worst,
309	        mean,
310	        settle,
311	    })
312	}
313	
314	/// Run the selftest and return the process exit code: 0 when the
315	/// machine qualifies, 1 when it does not, 2 on a spawn/parse
316	/// failure.
317	pub fn run(cfg: &QualifyCfg) -> i32 {
318	    println!(
319	        "qualify-environment: {} runs of `{CHILD_BENCH} -d {}`, gap {}s{}",
320	        cfg.runs,
321	        cfg.duration_s,
322	        cfg.gap_s,
323	        match &cfg.pin_cpus {
324	            Some(p) => format!(", --pin-cpus {p}"),
325	            None => String::new(),
326	        }
327	    );
328	    println!("  the box is the subject: grades are the environment's, not the run's\n");
329	    println!("  run   warmup  bench    worst   settle                      mean");
330	
331	    let gap = Duration::from_secs_f64(cfg.gap_s.max(0.0));
332	    let mut runs: Vec<QualifyRun> = Vec::with_capacity(cfg.runs as usize);
333	    for i in 0..cfg.runs {
334	        std::thread::sleep(gap);
335	        match run_once(cfg) {
336	            Ok(r) => {
337	                let (w, d) = r.letters();
338	                // The state rides the settle column here too: which clock each
339	                // warmup certified is the fastest read on a two-state box, where
340	                // the settle times alone all look instant.
341	                let settle = match &r.settle {
342	                    Some(s) => s.to_string(),
343	                    None => "-".to_string(),
344	                };
345	                println!(
346	                    "  {:<5} {w:<7} {d:<8} {:<7} {settle:<27} {}",
347	                    i + 1,
348	                    r.worst,
349	                    r.mean
350	                );
351	                runs.push(r);
352	            }
353	            Err(e) => {
354	                eprintln!("error: qualify run {}: {e}", i + 1);
355	                return 2;
356	            }
357	        }
358	    }
359	
360	    let mut scores: Vec<i64> = runs.iter().map(|r| score(r.worst)).collect();
361	    scores.sort_unstable();
362	    let median = scores.get(scores.len() / 2).copied().unwrap_or(0); // OK: runs >= 1 enforced by the CLI
363	    let degraded = runs.iter().filter(|r| r.transition_degraded()).count();
364	
365	    // Never-settled runs enter as their reserved 0%, so the median is over every run that
366	    // reported a cell rather than only the ones that settled.
367	    let mut settles: Vec<f64> = runs
368	        .iter()
369	        .filter_map(|r| match r.settle {
370	            Some(Settle::At { settled_frac, .. }) => Some(settled_frac),
371	            Some(Settle::Never { .. }) => Some(0.0),
372	            None => None,
373	        })
374	        .collect();
375	    settles.sort_by(f64::total_cmp);
376	    let never = runs
377	        .iter()
378	        .filter(|r| matches!(r.settle, Some(Settle::Never { .. })))
379	        .count();
380	
381	    println!("\n  environment grades: {}", grade_tally(&runs));
382	    println!("  median environment grade: {}", letter_for(median));
383	    if let Some(&s) = settles.get(settles.len() / 2) {
384	        println!(
385	            "  median settled: {:.0}% of warmup ({never} of {} never settled)",
386	            s * 100.0,
387	            runs.len()
388	        );
389	    }
390	    println!(
391	        "  transition-degraded (drift or step at D/F): {degraded} of {}",
392	        runs.len()
393	    );
394	
395	    if cfg.print_only {
396	        println!("\n  verdict: skipped (--print-only)");
397	        return 0;
398	    }
399	    let pass = median >= 4 && degraded == 0;
400	    println!(
401	        "\n  verdict: {}",
402	        if pass { "QUALIFIED" } else { "NOT QUALIFIED" }
403	    );
404	    if !pass {
405	        if median < 4 {
406	            println!("    median grade below B: runs are measuring a moving box");
407	        }
408	        if degraded > 0 {
409	            println!("    a state transition landed inside a measurement window");
410	        }
411	        return 1;
412	    }
413	    0
414	}
415	
416	#[cfg(test)]
417	mod tests {
418	    use super::*;
419	
420	    #[test]
421	    fn stretch_reads_the_worst_column() {
422	        let cells = row_cells(
423	            "  env    warmup        0.86s      B    0.30% A       -       0.01% B   0.00% A            0.00% A",
424	        );
425	        let s = parse_stretch(&cells);
426	        assert_eq!(s.letter, 'B');
427	        assert_eq!(s.drift, Some('A'));
428	        assert_eq!(s.step, Some('A'));
429	        assert!(!s.transition_degraded());
430	    }
431	
432	    #[test]
433	    fn transition_detectors_are_drift_and_step_only() {
434	        // An F on interference is contamination, not a transition.
435	        let noisy = parse_stretch(&row_cells(
436	            "  env    bench             -      F    0.30% A       -      40.00% F   0.00% A            0.00% A",
437	        ));
438	        assert!(!noisy.transition_degraded());
439	        // A D on step is.
440	        let moved = parse_stretch(&row_cells(
441	            "  env    bench             -      D    0.30% A       -       0.01% A   0.10% A     6.50% @1.10s D",
442	        ));
443	        assert!(moved.transition_degraded());
444	    }
445	
446	    #[test]
447	    fn settle_cell_is_read_but_not_scored() {
448	        // The timing-only forms, 0% reserved for never-settled.
449	        assert_eq!(
450	            parse_settle("84%"),
451	            Some(Settle::At {
452	                t_s: 0.0,
453	                settled_frac: 0.84,
454	                start_ghz: None,
455	                ghz: None,
456	                rating: None
457	            })
458	        );
459	        assert_eq!(
460	            parse_settle("00%"),
461	            Some(Settle::Never {
462	                start_ghz: None,
463	                end_ghz: None
464	            })
465	        );
466	        // The journey forms: single spaces stay inside the cell.
467	        assert_eq!(
468	            parse_settle("4.84->5.24GHz 49% +-0.1%"),
469	            Some(Settle::At {
470	                t_s: 0.0,
471	                settled_frac: 0.49,
472	                start_ghz: Some(4.84),
473	                ghz: Some(5.24),
474	                rating: Some(0.1 / 100.0)
475	            })
476	        );
477	        assert_eq!(
478	            parse_settle("4.09->4.09GHz 100% +-0.1%"),
479	            Some(Settle::At {
480	                t_s: 0.0,
481	                settled_frac: 1.0,
482	                start_ghz: Some(4.09),
483	                ghz: Some(4.09),
484	                rating: Some(0.1 / 100.0)
485	            })
486	        );
487	        assert_eq!(
488	            parse_settle("3.60->4.20GHz 00%"),
489	            Some(Settle::Never {
490	                start_ghz: Some(3.6),
491	                end_ghz: Some(4.2)
492	            })
493	        );
494	        // The report appends the settle signal's letter; the parse strips it.
495	        assert_eq!(
496	            parse_settle("4.84->5.24GHz 49% +-0.1% D"),
497	            parse_settle("4.84->5.24GHz 49% +-0.1%")
498	        );
499	        // The bench and run rows carry a blank settle cell.
500	        assert_eq!(parse_settle("-"), None);
501	        // A never-settled warmup still scores from its own worst
502	        // column, never from the settle cell.
503	        let never = parse_stretch(&row_cells(
504	            "  env    warmup  3.65->4.53GHz 00% F      F    0.30% A       -       0.01% A   9.90% F            0.00% A",
505	        ));
506	        assert_eq!(never.letter, 'F');
507	        assert_eq!(never.drift, Some('F'));
508	    }
509	
510	    #[test]
511	    fn header_and_run_rows_are_not_stretches() {
512	        // Neither the header nor the `run all` row starts with
513	        // `env`, so run_once's row filter passes them by; this
514	        // pins the cell shapes it filters on.
515	        let header = row_cells(
516	            "  grade  phase        settle  worst     spread  bursts  interference     drift               step",
517	        );
518	        assert_eq!(header.first(), Some(&"grade"));
519	        let run = row_cells(
520	            "  run    all               -      D          -   33% B       2.59% B   2.93% C     9.37% @1.90s D",
521	        );
522	        assert_eq!(run.first(), Some(&"run"));
523	        assert_eq!(run.len(), 9);
524	    }
525	
526	    #[test]
527	    fn grade_tally_counts_every_letter_seen() {
528	        let run = |worst| QualifyRun {
529	            warmup: None,
530	            during: None,
531	            worst,
532	            mean: String::new(),
533	            settle: None,
534	        };
535	        let runs: Vec<QualifyRun> = "AAAAAAABDF".chars().map(run).collect();
536	        // The shape that motivated the line: a median of A over a
537	        // table showing three runs where the box moved.
538	        assert_eq!(grade_tally(&runs), "7A 1B 1D 1F");
539	        assert_eq!(grade_tally(&[]), "");
540	    }
541	
542	    #[test]
543	    fn unknown_letter_scores_worst() {
544	        assert_eq!(score('?'), score('F'));
545	        assert!(score('A') > score('B'));
546	    }
547	}
